#!/bin/bash
# Prueba de solo lectura de evaluar-imagenes-ocp.yml (salida liviana + CSV por bloque) contra el SNO. Sin secretos.
D=$HOME/openshift/sno; KC=$D/instalar/auth/kubeconfig; OC=$D/bin/oc
E0=$(sudo virsh domstate sno 2>&1 | head -1); echo "SNO_ESTADO_INICIAL: $E0"
if [ "$E0" != "running" ]; then echo "SNO apagado: no se enciende en esta corrida"; exit 0; fi
$OC --kubeconfig $KC get --raw /readyz >/dev/null 2>&1 || { echo "API no responde"; exit 0; }
W=/tmp/imgocp-$$; mkdir -p $W && cd $W
echo "" | base64 -d | tar xzf -
python3 -m venv $W/venv >/dev/null && $W/venv/bin/pip install -q "ansible>=8,<9" kubernetes 2>&1 | grep -v -i "warning\|upgrade\|notice" | tail -3
export PATH=$W/venv/bin:$D/bin:$PATH ANSIBLE_LOCALHOST_WARNING=False ANSIBLE_COLLECTIONS_PATH=$W/none
cd imagenes-ocp; ansible-playbook --syntax-check evaluar-imagenes-ocp.yml 2>&1 | grep -v WARNING | tail -3
T0=$(date +%s)
ansible-playbook evaluar-imagenes-ocp.yml -e ocp_kubeconfig=$KC -e reporte_dir=$W/out -e generar_jsonl=true > $W/run.log 2>&1; echo "RC $?"
grep -v -i -E "token|password|secret|bearer|certificate-authority-data|client-key" $W/run.log | grep -E 'fatal|ERROR|PLAY RECAP|localhost +:|"(Clúster|Registro|Espacio|Caché|Bloque|Aviso|Filas)' | cut -c1-300
echo "DURACION $(($(date +%s)-T0))s"
cd $W/out; ls -la */ *.tar.gz | awk 'NF>5{print $5, $9}'; tar tzf *.tar.gz | head -12
for f in */bloque*.csv */inventario-completo.csv; do echo "$f: $(($(wc -l < $f)-1)) filas"; done
head -1 */inventario-completo.csv | cut -c1-200
echo "== HTML_B64_INICIO"; gzip -9c */reporte.html | base64 -w0; echo; echo "== HTML_B64_FIN"
echo "debug ns restantes: $($OC --kubeconfig $KC get ns --no-headers 2>/dev/null | grep -c openshift-debug)"
cd /; rm -rf $W; echo "SNO_ESTADO_FINAL: $(sudo virsh domstate sno | head -1)"
